45	  const findNota = (data: Record<string, any> | undefined) => {
46	    if (!data) return null;
47	    if (data.nota_id) {
48	      return notas.find((n: any) => n.id === data.nota_id) || null;
49	    }
50	    if (data.fornecedor) {
51	      const term = String(data.fornecedor).toLowerCase();
52	      return notas.find((n: any) => n.fornecedor?.toLowerCase().includes(term)) || null;
53	    }
54	    if (data.numero_nota) {
55	      return notas.find((n: any) => n.numero_nota === data.numero_nota) || null;
56	    }
57	    return null;
